				"fontColor": "#D64550",
				"fontSize": "small",
				"markdown": "## About & Alerts"
			},
			"type": "splunk.markdown"
		},
		"viz_nrs_a": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 80,
						"value": "#D64550"
					},
					{
						"from": 80,
						"to": 95,
						"value": "#E5A823"
					},
					{
						"from": 95,
						"value": "#6EBE4A"
					}
				]
			},
			"dataSources": {
				"primary": "ds_score_a"
			},
			"description": "AP reach % — should be ≥ 95 before exercise",
			"options": {
				"backgroundColor": "#FFFFFF",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"unit": "%",
				"unitPosition": "after"
			},
			"title": "A — Attainability",
			"type": "splunk.singlevalue"
		},
		"viz_nrs_drisk": {
			"context": {
				"majorColorEditorConfig": [
					{
						"to": 85,
						"value": "#D64550"
					},
					{
						"from": 85,
						"to": 95,
						"value": "#E5A823"
					},
					{
						"from": 95,
						"value": "#6EBE4A"
					}
				]
			},
			"dataSources": {
				"primary": "ds_score_drisk"
			},
			"description": "Risk deflator from P1/P2/saturation — floor 0.5",
			"options": {
				"backgroundColor": "#FFFFFF",
				"majorColor": "> majorValue | rangeValue(majorColorEditorConfig)",
				"shouldAbbreviateMajorValue": true,
				"shouldAbbreviateTrendValue": true,
				"unit": "%",
				"unitPosition": "after"
			},
			"title": "D_risk — Risk Multiplier",
			"type": "splunk.singlevalue"
		},
		"viz_nrs_per_site_bar": {
			"dataSources": {
				"primary": "ds_score_per_site_nrs_only"
			},
			"description": "NRS per site (Tallahassee: SEOC, Tallahassee: Betty Easley, Auburndale: AUB, Auburndale: Warehouse). Lowest bar = weakest building right now.",
			"eventHandlers": [
				{
					"options": {
						"tokens": [
							{
								"key": "row.Site.value",
								"token": "site_filter"
							}
						]
					},
					"type": "drilldown.setToken"
				}
			],
			"options": {
				"dataValuesDisplay": "all",
				"legendDisplay": "off",
				"seriesColors": [
					"#049FD9"
				],
				"showRoundedY": true,
				"xAxisTitleVisibility": "hide",
