		}
	},
	"dataSources": {
		"ds_a_nrs_forecast": {
			"name": "NRS hourly with 24h forecast",
			"options": {
				"query": "| union [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" OverallHealth=* \n | search DeviceFamily=\"Unified AP\" OR DeviceFamily=\"Wireless Controller\" \n | where OverallHealth >= 0 \n | bin _time \n | stats latest(Reachability) as reach, latest(OverallHealth) as oh by _time, DeviceName \n | eval is_reach=if(upper(reach)=\"REACHABLE\", 1, 0), ap_ok=if(oh>=`nrs_th_ap_health`, 1, 0) \n | stats avg(is_reach) as ap_reach, avg(ap_ok) as ap_health_ok, count as ap_n by _time ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\" \n | eval cl_health = 'health.overallScore' \n | bin _time \n | stats avg(cl_health) as health_avg, count(eval(cl_health>=`nrs_th_cl_health`)) as ok_n, count as cl_n by _time \n | eval cl_ok=if(cl_n>0, ok_n/cl_n, null()), health100=coalesce(health_avg,8)*10 ] \n| stats values(ap_reach) as ap_reach, values(ap_health_ok) as ap_ok,\n values(cl_ok) as cl_ok, values(health100) as h100,\n values(ap_n) as ap_n, values(cl_n) as cl_n by _time \n| eval ap_reach=coalesce(ap_reach,1), ap_ok=coalesce(ap_ok,1),\n cl_ok=coalesce(cl_ok,1), h100=coalesce(h100,80) \n| eval A=ap_reach*100, R=(ap_ok*0.5 + cl_ok*0.5)*100, Q=h100 \n| eval NRS=A*`nrs_w_nrs_a` + R*`nrs_w_nrs_r` + Q*`nrs_w_nrs_q` \n| timechart max(eval(round(NRS, 2))) as NRS \n| predict NRS as predicted future_timespan=24 \n| rename \"upper95(prediction(NRS))\" as upper95,\n \"lower95(prediction(NRS))\" as lower95 \n| eval predicted=round(predicted, 2), upper95=round(upper95, 2), lower95=round(lower95, 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_annotations": {
			"name": "Shared - ds_annotations",
			"options": {
				"query": "| noop",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_b_capacity_gauge": {
			"name": "Tab B - Overall Capacity Utilization",
			"options": {
				"query": "| union\n [ search `index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\"\n | `spaces_hierarchy(deviceCounts)`\n | eval users=tonumber(mvindex('deviceCounts.userCount',0))\n | where isnotnull(users) AND isnotnull(building) AND building!=\"\"\n | bin _time span=15m\n | stats max(users) as users by _time, site\n | stats sum(users) as total_users by _time\n | stats max(total_users) as selected_peak_users ]\n [ search earliest=-24h latest=now `index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_COUNT\"\n | `spaces_hierarchy(deviceCounts)`\n | eval users=tonumber(mvindex('deviceCounts.userCount',0))\n | where isnotnull(users) AND isnotnull(building) AND building!=\"\"\n | bin _time span=15m\n | stats max(users) as users by _time, site\n | stats sum(users) as total_users by _time\n | stats max(total_users) as fallback_peak_users ]\n| stats max(selected_peak_users) as selected_peak_users, max(fallback_peak_users) as fallback_peak_users\n| eval total_peak_users=coalesce(selected_peak_users, fallback_peak_users, 0)\n| appendcols\n [ search earliest=-24h latest=now `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\"\n | stats dc(DeviceName) as total_aps ]\n| eval total_aps=coalesce(total_aps, 0), total_capacity=total_aps*30\n| eval used_pct=if(total_capacity>0, round(total_peak_users/total_capacity*100, 1), 0)\n| fields used_pct",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_c_issues_forecast": {
			"name": "Active issues hourly with 24h forecast",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n| timechart dc(IssueID) as \"Active Issues\"\n| predict \"Active Issues\" as predicted future_timespan=24\n| rename \"upper95(prediction(Active Issues))\" as upper95,\n \"lower95(prediction(Active Issues))\" as lower95\n| eval predicted=round(predicted, 2), upper95=round(upper95, 2), lower95=round(lower95, 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_correlation_strip": {
			"name": "Multi-source correlation - DNAC AP Health and Issues with Spaces Concurrent Users",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" OverallHealth=*\n| search DeviceFamily=\"Unified AP\" OR DeviceFamily=\"Wireless Controller\"\n| eval oh = tonumber(mvindex(OverallHealth, 0))\n| where isnotnull(oh) AND oh >= 0\n| timechart avg(oh) as ap_health_raw\n| eval ap_health_raw = if(ap_health_raw=0, null(), ap_health_raw)\n| filldown ap_health_raw\n| eval \"DNAC AP Health (0-100)\" = round(ap_health_raw*10, 2)\n| fields - ap_health_raw\n| appendcols\n [ search `index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n | timechart dc(IssueID) as snap\n | eval snap = if(snap=0, null(), snap)\n | filldown snap\n | rename snap as \"DNAC Active Issues\" ]\n| appendcols\n [ search `index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n | eval mac=coalesce('devicePresence.device.macAddress','devicePresence.macAddress')\n | where isnotnull(mac) AND mac!=\"\"\n | timechart dc(mac) as spaces_users\n | eval spaces_users = if(spaces_users=0, null(), spaces_users)\n | filldown spaces_users\n | rename spaces_users as \"Spaces Concurrent Users\" ]",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_d_wow_users": {
			"name": "Spaces concurrent users this week vs last week",
			"options": {
				"query": "| union \n [ search `index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n earliest=-7d@h latest=@h\n | eval mac=coalesce('devicePresence.device.macAddress','devicePresence.macAddress')\n | where isnotnull(mac) AND mac!=\"\"\n | bin _time \n | stats dc(mac) as \"This week\" by _time ]\n [ search `index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n earliest=-14d@h latest=-7d@h\n | eval mac=coalesce('devicePresence.device.macAddress','devicePresence.macAddress')\n | where isnotnull(mac) AND mac!=\"\"\n | eval _time = _time + 604800\n | bin _time \n | stats dc(mac) as \"Last week\" by _time ]\n| timechart max(\"This week\") as \"This week\", max(\"Last week\") as \"Last week\"\n",
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_q10_recovery_health": {
			"name": "Q10a - DNAC avg client health over time",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| eval cl_health = 'health.overallScore'\n| timechart avg(cl_health) as \"Avg Client Health\"\n| eval \"Avg Client Health\" = round('Avg Client Health', 2)",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q10_recovery_issues": {
			"name": "Q10c - DNAC issue count over time",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n| timechart dc(IssueID) as \"Active Issues\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q10_recovery_onboarding": {
			"name": "Q10b - DNAC avg onboarding time over time",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| eval onb_ms = 'onboarding.avgRunDuration'\n| where isnotnull(onb_ms) AND onb_ms>0\n| timechart avg(onb_ms) as \"Avg Onboarding ms\"\n| eval \"Avg Onboarding Seconds\" = round('Avg Onboarding ms'/1000, 2)\n| fields - \"Avg Onboarding ms\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q1_people_per_ap": {
			"name": "Q1 - Spaces x DNAC users-to-AP ratio per site",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n| eval lh_t0='devicePresence.location.inferredLocationTypes{}',\n lh_t1='devicePresence.location.parent.inferredLocationTypes{}',\n lh_t2='devicePresence.location.parent.parent.inferredLocationTypes{}',\n lh_t3='devicePresence.location.parent.parent.parent.inferredLocationTypes{}',\n lh_t4='devicePresence.location.parent.parent.parent.parent.inferredLocationTypes{}',\n lh_n0='devicePresence.location.name',\n lh_n1='devicePresence.location.parent.name',\n lh_n2='devicePresence.location.parent.parent.name',\n lh_n3='devicePresence.location.parent.parent.parent.name',\n lh_n4='devicePresence.location.parent.parent.parent.parent.name'\n| eval building=case(mvfind(lh_t0,\"NETWORK\")>=0,lh_n0, mvfind(lh_t1,\"NETWORK\")>=0,lh_n1, mvfind(lh_t2,\"NETWORK\")>=0,lh_n2, mvfind(lh_t3,\"NETWORK\")>=0,lh_n3, mvfind(lh_t4,\"NETWORK\")>=0,lh_n4)\n| eval campus=case(mvfind(lh_t0,\"CAMPUS\")>=0,lh_n0, mvfind(lh_t1,\"CAMPUS\")>=0,lh_n1, mvfind(lh_t2,\"CAMPUS\")>=0,lh_n2, mvfind(lh_t3,\"CAMPUS\")>=0,lh_n3, mvfind(lh_t4,\"CAMPUS\")>=0,lh_n4)\n| where isnotnull(campus) AND isnotnull(building)\n| eval site=campus.\": \".building\n| fields - lh_t0 lh_t1 lh_t2 lh_t3 lh_t4 lh_n0 lh_n1 lh_n2 lh_n3 lh_n4\n| eval mac=coalesce('devicePresence.device.macAddress','devicePresence.macAddress')\n| where isnotnull(mac) AND mac!=\"\"\n| bin _time\n| stats dc(mac) as users by _time, site\n| stats max(users) as peak_users by site\n| append\n [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\"\n | eval site_raw=coalesce(Site, Location)\n | where isnotnull(site_raw) AND trim(site_raw)!=\"\" AND lower(site_raw)!=\"null\"\n | eval s_parts=split(site_raw, \"/\"), s_campus=mvindex(s_parts, 2), s_building=mvindex(s_parts, 3)\n | where isnotnull(s_campus) AND isnotnull(s_building)\n | eval site=s_campus.\": \".s_building\n | stats dc(DeviceName) as ap_count by site ]\n| stats values(peak_users) as peak_users, values(ap_count) as ap_count by site\n| where isnotnull(site)\n| eval peak_users=coalesce(peak_users,0), ap_count=coalesce(ap_count,0)\n| eval ratio=if(ap_count>0, round(peak_users/ap_count, 2), null()),\n status=case(ap_count=0, \"NO APs\",\n ratio<20, \"Healthy\",\n ratio<30, \"Watch\",\n ratio<50, \"At Risk\",\n 1=1, \"Saturation Risk\")\n| sort -ratio\n| rename site as \"Site\", peak_users as \"Peak Users\", ap_count as \"APs\",\n ratio as \"Users per AP\", status as \"Status\"\n| table \"Site\" \"Peak Users\" \"APs\" \"Users per AP\" \"Status\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q2_capacity_headroom": {
			"name": "Q2 - Spaces x DNAC capacity headroom per site",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n| eval lh_t0='devicePresence.location.inferredLocationTypes{}',\n lh_t1='devicePresence.location.parent.inferredLocationTypes{}',\n lh_t2='devicePresence.location.parent.parent.inferredLocationTypes{}',\n lh_t3='devicePresence.location.parent.parent.parent.inferredLocationTypes{}',\n lh_t4='devicePresence.location.parent.parent.parent.parent.inferredLocationTypes{}',\n lh_n0='devicePresence.location.name',\n lh_n1='devicePresence.location.parent.name',\n lh_n2='devicePresence.location.parent.parent.name',\n lh_n3='devicePresence.location.parent.parent.parent.name',\n lh_n4='devicePresence.location.parent.parent.parent.parent.name'\n| eval building=case(mvfind(lh_t0,\"NETWORK\")>=0,lh_n0, mvfind(lh_t1,\"NETWORK\")>=0,lh_n1, mvfind(lh_t2,\"NETWORK\")>=0,lh_n2, mvfind(lh_t3,\"NETWORK\")>=0,lh_n3, mvfind(lh_t4,\"NETWORK\")>=0,lh_n4)\n| eval campus=case(mvfind(lh_t0,\"CAMPUS\")>=0,lh_n0, mvfind(lh_t1,\"CAMPUS\")>=0,lh_n1, mvfind(lh_t2,\"CAMPUS\")>=0,lh_n2, mvfind(lh_t3,\"CAMPUS\")>=0,lh_n3, mvfind(lh_t4,\"CAMPUS\")>=0,lh_n4)\n| where isnotnull(campus) AND isnotnull(building)\n| eval site=campus.\": \".building\n| fields - lh_t0 lh_t1 lh_t2 lh_t3 lh_t4 lh_n0 lh_n1 lh_n2 lh_n3 lh_n4\n| eval mac=coalesce('devicePresence.device.macAddress','devicePresence.macAddress')\n| where isnotnull(mac) AND mac!=\"\"\n| bin _time\n| stats dc(mac) as users by _time, site\n| stats max(users) as peak_users by site\n| append\n [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\"\n | eval site_raw=coalesce(Site, Location)\n | where isnotnull(site_raw) AND trim(site_raw)!=\"\" AND lower(site_raw)!=\"null\"\n | eval s_parts=split(site_raw, \"/\"), s_campus=mvindex(s_parts, 2), s_building=mvindex(s_parts, 3)\n | where isnotnull(s_campus) AND isnotnull(s_building)\n | eval site=s_campus.\": \".s_building\n | stats dc(DeviceName) as ap_count by site ]\n| stats values(peak_users) as peak_users, values(ap_count) as ap_count by site\n| where isnotnull(site)\n| eval peak_users=coalesce(peak_users,0), ap_count=coalesce(ap_count,0)\n| eval capacity=ap_count*30,\n used_pct=if(capacity>0, round(peak_users/capacity*100, 2), null()),\n headroom_pct=if(capacity>0, round(100-(peak_users/capacity*100), 2), null())\n| sort -used_pct\n| rename site as \"Site\", ap_count as \"APs\", capacity as \"Capacity\",\n peak_users as \"Peak Users\", used_pct as \"Used Pct\",\n headroom_pct as \"Headroom Pct\"\n| table \"Site\" \"APs\" \"Capacity\" \"Peak Users\" \"Used Pct\" \"Headroom Pct\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q3_aps_poor_health": {
			"name": "Q3 - DNAC APs to fix before the exercise",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\"\n| eval site_raw=coalesce(Site, Location, \"Unsited\")\n| stats latest(OverallHealth) as oh,\n latest(Reachability) as Reachability,\n latest(IssueCount) as Issues by DeviceName, site_raw\n| where (oh<7 OR upper(Reachability)!=\"REACHABLE\" OR Issues>0)\n| eval Health = case(upper(Reachability)!=\"REACHABLE\", \"—\", isnull(oh), \"—\", oh<0, \"—\", 1=1, tostring(oh))\n| eval Status=case(upper(Reachability)!=\"REACHABLE\", \"UNREACHABLE\",\n isnotnull(oh) AND oh>=0 AND oh<5, \"Critical\",\n isnotnull(oh) AND oh<7, \"Degraded\",\n Issues>0, \"Has Issues\",\n 1=1, \"Watch\")\n| eval site=replace(site_raw, \"^Global/Florida/\", \"\")\n| sort + oh\n| rename DeviceName as \"AP\", site as \"Site\", Issues as \"Open Issues\"\n| table \"AP\" \"Site\" \"Health\" \"Reachability\" \"Open Issues\" \"Status\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q4_concurrent_users": {
			"name": "Q4b - Spaces concurrent users per site",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n| eval lh_t0='devicePresence.location.inferredLocationTypes{}',\n lh_t1='devicePresence.location.parent.inferredLocationTypes{}',\n lh_t2='devicePresence.location.parent.parent.inferredLocationTypes{}',\n lh_t3='devicePresence.location.parent.parent.parent.inferredLocationTypes{}',\n lh_t4='devicePresence.location.parent.parent.parent.parent.inferredLocationTypes{}',\n lh_n0='devicePresence.location.name',\n lh_n1='devicePresence.location.parent.name',\n lh_n2='devicePresence.location.parent.parent.name',\n lh_n3='devicePresence.location.parent.parent.parent.name',\n lh_n4='devicePresence.location.parent.parent.parent.parent.name'\n| eval building=case(mvfind(lh_t0,\"NETWORK\")>=0,lh_n0, mvfind(lh_t1,\"NETWORK\")>=0,lh_n1, mvfind(lh_t2,\"NETWORK\")>=0,lh_n2, mvfind(lh_t3,\"NETWORK\")>=0,lh_n3, mvfind(lh_t4,\"NETWORK\")>=0,lh_n4)\n| eval campus=case(mvfind(lh_t0,\"CAMPUS\")>=0,lh_n0, mvfind(lh_t1,\"CAMPUS\")>=0,lh_n1, mvfind(lh_t2,\"CAMPUS\")>=0,lh_n2, mvfind(lh_t3,\"CAMPUS\")>=0,lh_n3, mvfind(lh_t4,\"CAMPUS\")>=0,lh_n4)\n| where isnotnull(campus) AND isnotnull(building)\n| eval site=campus.\": \".building\n| fields - lh_t0 lh_t1 lh_t2 lh_t3 lh_t4 lh_n0 lh_n1 lh_n2 lh_n3 lh_n4\n| eval mac=coalesce('devicePresence.device.macAddress','devicePresence.macAddress')\n| where isnotnull(mac) AND mac!=\"\"\n| timechart useother=t dc(mac) as \"Concurrent Users\" by site where max in top10\n| addtotals fieldname=\"Total network-wide\"\n| appendcols\n [ search `index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n | timechart dc(IssueID) as \"DNAC Active Issues\" ]",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q4_onboarding_per_site": {
			"name": "Q4a - DNAC onboarding time per site",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| eval site = siteHierarchy\n| where isnotnull(site) AND trim(site)!=\"\" AND lower(site)!=\"null\" AND NOT match(site, \"(?i)(^|/)null(/|$)\") AND NOT match(site, \"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\")\n| eval onb_ms = 'onboarding.avgRunDuration'\n| where isnotnull(onb_ms) AND onb_ms>0\n| bin _time\n| stats avg(onb_ms) as onb_ms by _time, site\n| eval \"Onboarding Seconds\" = round(onb_ms/1000, 2)\n| xyseries _time site \"Onboarding Seconds\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q5_ap_saturation": {
			"name": "Q5 - DNAC AP saturation top 30 column heatmap",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\" (ClientCountGhz24=* OR ClientCountRadio0=*)\n| eval g24 = tonumber(mvindex(ClientCountGhz24, 0)),\n g50 = tonumber(mvindex(ClientCountGhz50, 0)),\n r0 = tonumber(mvindex(ClientCountRadio0, 0)),\n r1 = tonumber(mvindex(ClientCountRadio1, 0))\n| eval radio_sum = coalesce(r0,0) + coalesce(r1,0),\n band_sum = coalesce(g24,0) + coalesce(g50,0)\n| eval clients = if(radio_sum >= band_sum, radio_sum, band_sum)\n| eventstats max(clients) as peak_per_ap by DeviceName\n| timechart max(clients) by DeviceName limit=30 useother=f\n| addtotals fieldname=\"Total clients (all APs)\"\n| appendcols\n [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\" (ClientCountGhz24=* OR ClientCountRadio0=*)\n | eval g24 = tonumber(mvindex(ClientCountGhz24, 0)),\n g50 = tonumber(mvindex(ClientCountGhz50, 0)),\n r0 = tonumber(mvindex(ClientCountRadio0, 0)),\n r1 = tonumber(mvindex(ClientCountRadio1, 0))\n | eval radio_sum = coalesce(r0,0) + coalesce(r1,0),\n band_sum = coalesce(g24,0) + coalesce(g50,0)\n | eval clients = if(radio_sum >= band_sum, radio_sum, band_sum)\n | eval saturated = if(clients > `nrs_ap_saturation_clients`, 1, 0)\n | timechart sum(saturated) as \"APs over threshold\" ]",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q5_at_risk_count": {
			"name": "Q5 - DNAC APs over 30 clients - saturation count",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\" (ClientCountGhz24=* OR ClientCountRadio0=*)\n| eval g24 = tonumber(mvindex(ClientCountGhz24, 0)),\n g50 = tonumber(mvindex(ClientCountGhz50, 0)),\n r0 = tonumber(mvindex(ClientCountRadio0, 0)),\n r1 = tonumber(mvindex(ClientCountRadio1, 0))\n| eval radio_sum = coalesce(r0,0) + coalesce(r1,0),\n band_sum = coalesce(g24,0) + coalesce(g50,0)\n| eval clients = if(radio_sum >= band_sum, radio_sum, band_sum)\n| stats max(clients) as peak by DeviceName\n| stats count as total_aps,\n count(eval(peak>`nrs_ap_saturation_clients`)) as at_risk\n| eval at_risk = coalesce(at_risk, 0)\n| eval label = at_risk.\" / \".total_aps\n| table at_risk label total_aps",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q6_issues_severity": {
			"name": "Q6 - DNAC issues stacked by severity",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n| eval prio=coalesce(IssuePriority, \"Other\")\n| timechart dc(IssueID) by prio\n| addtotals fieldname=\"Total active issues\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q6_occupancy_overlay": {
			"name": "Q6 - Spaces total concurrent users overlay",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n| eval mac=coalesce('devicePresence.device.macAddress','devicePresence.macAddress')\n| where isnotnull(mac) AND mac!=\"\"\n| timechart dc(mac) as \"Total Concurrent Users\"\n| appendcols\n [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\" (ClientCountGhz24=* OR ClientCountRadio0=*)\n | eval g24 = tonumber(mvindex(ClientCountGhz24, 0)),\n g50 = tonumber(mvindex(ClientCountGhz50, 0)),\n r0 = tonumber(mvindex(ClientCountRadio0, 0)),\n r1 = tonumber(mvindex(ClientCountRadio1, 0))\n | eval radio_sum = coalesce(r0,0) + coalesce(r1,0),\n band_sum = coalesce(g24,0) + coalesce(g50,0)\n | eval clients = if(radio_sum >= band_sum, radio_sum, band_sum)\n | eval saturated = if(clients > `nrs_ap_saturation_clients`, 1, 0)\n | timechart sum(saturated) as \"APs over saturation threshold\" ]",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q7_ssid_concurrency": {
			"name": "Q7 - Spaces per-SSID concurrent associations",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\"\n| eval ssid=coalesce('deviceAssociation.ssid', \"(unknown)\"),\n mac=coalesce('deviceAssociation.device.macAddress','deviceAssociation.macAddress')\n| where isnotnull(mac) AND mac!=\"\"\n| timechart useother=t dc(mac) as concurrent by ssid where max in top10\n| addtotals fieldname=\"Total stacked (sum)\"\n| appendcols\n [ search `index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_ASSOCIATION\" deviceAssociation.event=\"ASSOCIATE\"\n | eval mac=coalesce('deviceAssociation.device.macAddress','deviceAssociation.macAddress')\n | where isnotnull(mac) AND mac!=\"\"\n | timechart dc(mac) as \"Total unique devices\" ]",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q8_surge_per_building": {
			"name": "Q8 - Spaces surge multiplier per building",
			"options": {
				"query": "`index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n| eval lh_t0='devicePresence.location.inferredLocationTypes{}',\n lh_t1='devicePresence.location.parent.inferredLocationTypes{}',\n lh_t2='devicePresence.location.parent.parent.inferredLocationTypes{}',\n lh_t3='devicePresence.location.parent.parent.parent.inferredLocationTypes{}',\n lh_t4='devicePresence.location.parent.parent.parent.parent.inferredLocationTypes{}',\n lh_n0='devicePresence.location.name',\n lh_n1='devicePresence.location.parent.name',\n lh_n2='devicePresence.location.parent.parent.name',\n lh_n3='devicePresence.location.parent.parent.parent.name',\n lh_n4='devicePresence.location.parent.parent.parent.parent.name'\n| eval building=case(mvfind(lh_t0,\"NETWORK\")>=0,lh_n0, mvfind(lh_t1,\"NETWORK\")>=0,lh_n1, mvfind(lh_t2,\"NETWORK\")>=0,lh_n2, mvfind(lh_t3,\"NETWORK\")>=0,lh_n3, mvfind(lh_t4,\"NETWORK\")>=0,lh_n4)\n| eval campus=case(mvfind(lh_t0,\"CAMPUS\")>=0,lh_n0, mvfind(lh_t1,\"CAMPUS\")>=0,lh_n1, mvfind(lh_t2,\"CAMPUS\")>=0,lh_n2, mvfind(lh_t3,\"CAMPUS\")>=0,lh_n3, mvfind(lh_t4,\"CAMPUS\")>=0,lh_n4)\n| where isnotnull(campus) AND isnotnull(building)\n| eval site=campus.\": \".building\n| fields - lh_t0 lh_t1 lh_t2 lh_t3 lh_t4 lh_n0 lh_n1 lh_n2 lh_n3 lh_n4\n| eval mac=coalesce('devicePresence.device.macAddress','devicePresence.macAddress')\n| where isnotnull(mac) AND mac!=\"\"\n| bin _time\n| stats dc(mac) as users by _time, site\n| eval bucket=case(_time>=relative_time(now(),\"@d-13d\") AND _time<relative_time(now(),\"@d-7d\"), \"Baseline\",\n _time>=relative_time(now(),\"@d-3d\") AND _time<=now(), \"Exercise\")\n| where isnotnull(bucket)\n| stats avg(users) as avg_users by site, bucket\n| xyseries site bucket avg_users\n| eval Multiplier=if(Baseline>0, round(Exercise/Baseline,2), null())\n| sort - Multiplier",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_q9_worst_clients": {
			"name": "Q9 - DNAC top 50 worst client experiences",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:client\"\n| eval cl_health = 'health.overallScore',\n site = siteHierarchy,\n ssid = 'connection.ssid',\n rssi = 'connection.rssi'\n| where isnotnull(macAddress) AND isnotnull(site) AND trim(site)!=\"\" AND lower(site)!=\"null\" AND NOT match(site, \"(?i)(^|/)null(/|$)\")\n| stats min(cl_health) as min_h, avg(cl_health) as avg_h,\n latest(ssid) as ssid, latest(rssi) as rssi by macAddress, site\n| where min_h<5\n| sort + min_h\n| head 50\n| eval avg_h=round(avg_h, 2), rssi=round(rssi, 2)\n| eval site=replace(site, \"^Global/Florida/\", \"\")\n| rename macAddress as \"Client MAC\", site as \"Site\", ssid as \"SSID\",\n rssi as \"RSSI\", min_h as \"Min Health\", avg_h as \"Avg Health\"\n| table \"Client MAC\" \"Site\" \"SSID\" \"RSSI\" \"Min Health\" \"Avg Health\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_score_a": {
			"name": "NRS A - Attainability - pct APs reachable",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\"\n| stats latest(Reachability) as reach by DeviceName\n| eval ok=if(upper(reach)=\"REACHABLE\", 1, 0)\n| stats avg(ok) as ap_reach_pct\n| eval score=round(coalesce(ap_reach_pct,1)*100, 2)\n| fields score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_score_drisk": {
			"name": "NRS D_risk - Risk multiplier",
			"options": {
				"query": "`index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n| stats dc(eval(case(IssuePriority=\"P1\", IssueID))) as p1,\n dc(eval(case(IssuePriority=\"P2\", IssueID))) as p2\n| eval p1=coalesce(p1,0), p2=coalesce(p2,0)\n| eval drisk = 1 - 0.05*p1 - 0.02*p2\n| eval drisk=if(drisk<0.5, 0.5, drisk)\n| eval score=round(drisk, 2)\n| fields score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_score_nrs": {
			"name": "NRS - Composite Network Readiness Score",
			"options": {
				"query": "| union [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\" OverallHealth=*\n | where OverallHealth >= 0\n | stats latest(Reachability) as reach, latest(OverallHealth) as oh by DeviceName\n | eval is_reach=if(upper(reach)=\"REACHABLE\", 1, 0), ap_ok=if(oh>=`nrs_th_ap_health`, 1, 0)\n | stats avg(is_reach) as ap_reach, avg(ap_ok) as ap_health_ok\n | eval kind=\"ap\" ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\"\n | eval cl_health = 'health.overallScore'\n | stats avg(cl_health) as health_avg, count(eval(cl_health>=`nrs_th_cl_health`)) as ok_n, count as tot_n\n | eval cl_ok=if(tot_n>0, ok_n/tot_n, 1), health100=coalesce(health_avg,8)*10\n | eval kind=\"client\" ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\"\n | eval ob_ms = 'onboarding.avgRunDuration'\n | where isnotnull(ob_ms) AND ob_ms>0\n | stats avg(ob_ms) as ob_ms\n | eval ob_s=coalesce(ob_ms,1500)/1000, onb100=if(ob_s<=1, 100, if(ob_s>=5, 0, 100-((ob_s-1)*25)))\n | eval kind=\"onb\" ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n | stats dc(eval(case(IssuePriority=\"P1\", IssueID))) as p1,\n dc(eval(case(IssuePriority=\"P2\", IssueID))) as p2\n | eval kind=\"risk\" ]\n| stats values(ap_reach) as ap_reach, values(ap_health_ok) as ap_ok,\n values(cl_ok) as cl_ok, values(health100) as h100,\n values(onb100) as o100, values(p1) as p1, values(p2) as p2\n| eval ap_reach=coalesce(ap_reach,1), ap_ok=coalesce(ap_ok,1), cl_ok=coalesce(cl_ok,1),\n h100=coalesce(h100,80), o100=coalesce(o100,80), p1=coalesce(p1,0), p2=coalesce(p2,0)\n| eval A=ap_reach*100, R=(ap_ok*0.5 + cl_ok*0.5)*100,\n Q=(h100*0.6 + o100*0.4),\n drisk_raw=1.0 - 0.05*p1 - 0.02*p2,\n D_risk=if(drisk_raw<0.5, 0.5, drisk_raw)\n| eval score=(A*`nrs_w_nrs_a` + R*`nrs_w_nrs_r` + Q*`nrs_w_nrs_q`) * D_risk\n| eval score=round(score, 2)\n| fields score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_score_nrs_spark": {
			"name": "NRS sparkline series",
			"options": {
				"extend": "ds_score_nrs_trend",
				"query": "| fields _time NRS"
			},
			"type": "ds.chain"
		},
		"ds_score_nrs_trend": {
			"name": "NRS over time hourly",
			"options": {
				"query": "| union [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" OverallHealth=*\n | search DeviceFamily=\"Unified AP\" OR DeviceFamily=\"Wireless Controller\"\n | where OverallHealth >= 0\n | bin _time\n | stats latest(Reachability) as reach, latest(OverallHealth) as oh by _time, DeviceName\n | eval is_reach=if(upper(reach)=\"REACHABLE\", 1, 0), ap_ok=if(oh>=`nrs_th_ap_health`, 1, 0)\n | stats avg(is_reach) as ap_reach, avg(ap_ok) as ap_health_ok, count as ap_n by _time ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\"\n | eval cl_health = 'health.overallScore'\n | bin _time\n | stats avg(cl_health) as health_avg, count(eval(cl_health>=`nrs_th_cl_health`)) as ok_n, count as cl_n by _time\n | eval cl_ok=if(cl_n>0, ok_n/cl_n, null()), health100=coalesce(health_avg,8)*10 ]\n| stats values(ap_reach) as ap_reach, values(ap_health_ok) as ap_ok,\n values(cl_ok) as cl_ok, values(health100) as h100,\n values(ap_n) as ap_n, values(cl_n) as cl_n by _time\n| where (isnotnull(ap_n) AND ap_n>0) OR (isnotnull(cl_n) AND cl_n>0)\n| eval ap_reach=coalesce(ap_reach,1), ap_ok=coalesce(ap_ok,1), cl_ok=coalesce(cl_ok,1), h100=coalesce(h100,80)\n| eval A=ap_reach*100, R=(ap_ok*0.5 + cl_ok*0.5)*100, Q=h100\n| eval NRS=A*`nrs_w_nrs_a` + R*`nrs_w_nrs_r` + Q*`nrs_w_nrs_q`\n| timechart avg(NRS) as \"NRS\"\n| eval \"NRS\" = round('NRS', 2)\n| appendcols\n [ search `index_catalyst` sourcetype=\"cisco:dnac:issue\" IssueStatus=\"active\"\n | timechart dc(IssueID) as \"DNAC Active Issues\" ]\n| appendcols\n [ search `index_spaces` sourcetype=\"cisco:spaces:firehose\" eventType=\"DEVICE_PRESENCE\"\n | eval mac=coalesce('devicePresence.device.macAddress','devicePresence.macAddress')\n | where isnotnull(mac) AND mac!=\"\"\n | timechart dc(mac) as \"Spaces Concurrent Users (overlay)\" ]",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_score_per_site": {
			"name": "NRS per site - DNAC AP and client health",
			"options": {
				"query": "| union [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\"\n | search DeviceFamily=\"Unified AP\" OR DeviceFamily=\"Wireless Controller\"\n | eval site=coalesce(Site, Location)\n | where isnotnull(site) AND trim(site)!=\"\" AND lower(site)!=\"null\" AND NOT match(site, \"(?i)(^|/)null(/|$)\") AND NOT match(site, \"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\")\n | stats latest(Reachability) as reach, latest(OverallHealth) as oh by DeviceName, site\n | eval is_reach=if(upper(reach)=\"REACHABLE\", 1, 0)\n | eval ap_ok=case(isnull(oh), null(), oh<0, null(), oh>=`nrs_th_ap_health`, 1, 1=1, 0)\n | stats avg(is_reach) as ap_reach, avg(ap_ok) as ap_health_ok, count as ap_n by site ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\" siteHierarchy=*\n | eval cl_health = 'health.overallScore', site = siteHierarchy\n | where isnotnull(site) AND trim(site)!=\"\" AND lower(site)!=\"null\" AND NOT match(site, \"(?i)(^|/)null(/|$)\") AND NOT match(site, \"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\")\n | stats avg(cl_health) as health_avg, count(eval(cl_health>=`nrs_th_cl_health`)) as ok_n, count as cl_n by site\n | eval cl_ok=if(cl_n>0, ok_n/cl_n, null()), health100=coalesce(health_avg,8)*10 ]\n| stats values(ap_reach) as ap_reach, values(ap_health_ok) as ap_ok,\n values(cl_ok) as cl_ok, values(health100) as h100,\n values(ap_n) as ap_n, values(cl_n) as cl_n by site\n| where isnotnull(site) AND trim(site)!=\"\" AND lower(site)!=\"null\" AND NOT match(site, \"(?i)(^|/)null(/|$)\")\n| where (isnotnull(ap_n) AND ap_n>0) OR (isnotnull(cl_n) AND cl_n>0)\n| eval ap_reach=coalesce(ap_reach,1), ap_ok=coalesce(ap_ok,1),\n cl_ok=coalesce(cl_ok,1), h100=coalesce(h100,80)\n| eval A=ap_reach*100, R=(ap_ok*0.5 + cl_ok*0.5)*100, Q=h100\n| eval NRS=A*`nrs_w_nrs_a` + R*`nrs_w_nrs_r` + Q*`nrs_w_nrs_q`\n| eval NRS=round(NRS, 2), A=round(A, 2), R=round(R, 2), Q=round(Q, 2)\n| eval site_short=replace(site, \"^Global/Florida/\", \"\")\n| sort -NRS\n| rename site_short as Site, ap_n as APs, cl_n as Clients\n| table Site NRS A R Q APs Clients",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_score_per_site_nrs_only": {
			"name": "ds_score_per_site_nrs_only",
			"options": {
				"query": "| union [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\"\n | search DeviceFamily=\"Unified AP\" OR DeviceFamily=\"Wireless Controller\"\n | eval site=coalesce(Site, Location)\n | where isnotnull(site) AND trim(site)!=\"\" AND lower(site)!=\"null\" AND NOT match(site, \"(?i)(^|/)null(/|$)\") AND NOT match(site, \"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\")\n | stats latest(Reachability) as reach, latest(OverallHealth) as oh by DeviceName, site\n | eval is_reach=if(upper(reach)=\"REACHABLE\", 1, 0)\n | eval ap_ok=case(isnull(oh), null(), oh<0, null(), oh>=`nrs_th_ap_health`, 1, 1=1, 0)\n | stats avg(is_reach) as ap_reach, avg(ap_ok) as ap_health_ok, count as ap_n by site ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\" siteHierarchy=*\n | eval cl_health = 'health.overallScore', site = siteHierarchy\n | where isnotnull(site) AND trim(site)!=\"\" AND lower(site)!=\"null\" AND NOT match(site, \"(?i)(^|/)null(/|$)\") AND NOT match(site, \"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$\")\n | stats avg(cl_health) as health_avg, count(eval(cl_health>=`nrs_th_cl_health`)) as ok_n, count as cl_n by site\n | eval cl_ok=if(cl_n>0, ok_n/cl_n, null()), health100=coalesce(health_avg,8)*10 ]\n| stats values(ap_reach) as ap_reach, values(ap_health_ok) as ap_ok,\n values(cl_ok) as cl_ok, values(health100) as h100,\n values(ap_n) as ap_n, values(cl_n) as cl_n by site\n| where isnotnull(site) AND trim(site)!=\"\" AND lower(site)!=\"null\" AND NOT match(site, \"(?i)(^|/)null(/|$)\")\n| where (isnotnull(ap_n) AND ap_n>0) OR (isnotnull(cl_n) AND cl_n>0)\n| eval ap_reach=coalesce(ap_reach,1), ap_ok=coalesce(ap_ok,1),\n cl_ok=coalesce(cl_ok,1), h100=coalesce(h100,80)\n| eval A=ap_reach*100, R=(ap_ok*0.5 + cl_ok*0.5)*100, Q=h100\n| eval NRS=A*`nrs_w_nrs_a` + R*`nrs_w_nrs_r` + Q*`nrs_w_nrs_q`\n| eval NRS=round(NRS, 2), A=round(A, 2), R=round(R, 2), Q=round(Q, 2)\n| eval site_short=replace(site, \"^Global/Florida/\", \"\")\n| sort -NRS\n| rename site_short as Site, ap_n as APs, cl_n as Clients\n| table Site NRS A R Q APs Clients\n| table Site NRS",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_score_q": {
			"name": "NRS Q - Quality - client health and onboarding",
			"options": {
				"query": "| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\"\n | eval cl_health = 'health.overallScore'\n | stats avg(cl_health) as health_avg\n | eval h100=coalesce(health_avg,8)*10\n | eval kind=\"health\" ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\"\n | eval ob_ms = 'onboarding.avgRunDuration'\n | where isnotnull(ob_ms) AND ob_ms>0\n | stats avg(ob_ms) as ob_ms\n | eval ob_s=coalesce(ob_ms,1500)/1000\n | eval o100=if(ob_s<=1, 100, if(ob_s>=5, 0, 100-((ob_s-1)*25)))\n | eval kind=\"onb\" ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\"\n | eval rv = 'connection.rssi'\n | stats avg(rv) as arv\n | eval r100=max(0, min(100, arv+100))\n | eval kind=\"rssi\" ]\n| stats values(h100) as h, values(o100) as o, values(r100) as r\n| eval h=coalesce(h,80), o=coalesce(o,80), r=coalesce(r,80)\n| eval score=0.35*h+0.35*o+0.30*r\n| eval score=round(score, 2)\n| fields score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		},
		"ds_score_r": {
			"name": "NRS R - Retainability - AP and client health mix",
			"options": {
				"query": "| union [ search `index_catalyst` sourcetype=\"cisco:dnac:devicehealth\" DeviceFamily=\"Unified AP\" OverallHealth=*\n | stats latest(OverallHealth) as h by DeviceName\n | eval ok=if(h>=`nrs_th_ap_health`, 1, 0)\n | stats avg(ok) as ap_health_ok\n | eval kind=\"ap\" ]\n| union [ search `index_catalyst` sourcetype=\"cisco:dnac:client\"\n | eval cs = 'health.overallScore'\n | where isnotnull(macAddress)\n | stats latest(cs) as cs by macAddress\n | eval ok=if(cs>=`nrs_th_cl_health`, 1, 0)\n | stats avg(ok) as client_health_ok\n | eval kind=\"client\" ]\n| stats values(ap_health_ok) as ap_h, values(client_health_ok) as cl_h\n| eval ap_h=coalesce(ap_h,1), cl_h=coalesce(cl_h,1)\n| eval score=round((ap_h*0.5 + cl_h*0.5)*100, 2)\n| fields score",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"refresh": "300s",
				"refreshType": "delay"
			},
			"type": "ds.search"
		}
	},
